from pathlib import Path
import json,hashlib,sys,subprocess,os
r=Path(sys.argv[1]);p=r/"payload";bundle=r/"result/synthetic-bundle"
def hashes():return {x.name:hashlib.sha256(x.read_bytes()).hexdigest() for x in bundle.iterdir()}
before=hashes();command=[str(r/"venv/bin/python"),"-B","-m","tools.a_dav.demo","--freeze",str(bundle)]
x=subprocess.run(command,cwd=p,env={"PYTHONDONTWRITEBYTECODE":"1","PYTEST_DISABLE_PLUGIN_AUTOLOAD":"1","OPENBLAS_NUM_THREADS":"1","OMP_NUM_THREADS":"1","MKL_NUM_THREADS":"1","NUMEXPR_NUM_THREADS":"1","VECLIB_MAXIMUM_THREADS":"1","BLIS_NUM_THREADS":"1","TZ":"UTC"},capture_output=True,text=True,timeout=120)
(r/"parent-resume.stdout.log").write_text(x.stdout);(r/"parent-resume.stderr.log").write_text(x.stderr)
files={}
for path in p.rglob("*"):
 assert not path.is_symlink()
 if path.is_file():files[path.relative_to(p).as_posix()]=hashlib.sha256(path.read_bytes()).hexdigest()
result={"classification":"SYNTHETIC_ONLY","command":command,"exit_code":x.returncode,"before_sha256":before,"after_sha256":hashes(),"payload_sha256":files,"real_source_data_used":False}
(r/"parent-resume.json").write_text(json.dumps(result,indent=2)+"\n")
print(json.dumps({"receipt":result,"stdout":x.stdout,"stderr":x.stderr}))
